<?php require_once __DIR__.'/includes/config.php';require_login();$uid=(int)$_SESSION['user_id'];
$q=$pdo->prepare('SELECT COALESCE(SUM(total),0) total, COALESCE(SUM(amount_paid),0) paid, COUNT(*) count FROM sales WHERE user_id=? AND created_at>=CURDATE() AND created_at<CURDATE()+INTERVAL 1 DAY');$q->execute([$uid]);$today=$q->fetch();
$q=$pdo->prepare('SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE user_id=? AND expense_date=CURDATE()');$q->execute([$uid]);$expenses=(float)$q->fetchColumn();
$q=$pdo->prepare('SELECT COUNT(*) FROM products WHERE user_id=?');$q->execute([$uid]);$productCount=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM products WHERE user_id=? AND quantity<=low_stock_threshold');$q->execute([$uid]);$lowStock=(int)$q->fetchColumn();
$q=$pdo->prepare('SELECT COALESCE(SUM(total-amount_paid),0) FROM sales WHERE user_id=?');$q->execute([$uid]);$debt=(float)$q->fetchColumn();
$q=$pdo->prepare('SELECT s.id,s.total,s.amount_paid,s.payment_method,s.created_at,c.name customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.user_id=? ORDER BY s.id DESC LIMIT 6');$q->execute([$uid]);$recent=$q->fetchAll();$pageTitle='Dashboard';require __DIR__.'/includes/header.php';?>
<div class="page-heading"><div><div class="text-secondary small">BUSINESS OVERVIEW</div><h1 class="h3 fw-bold mb-1">Good to see you, <?=e($_SESSION['full_name'])?></h1><p class="muted mb-0"><?=e($_SESSION['business_name'])?> · <?=date('l, j F Y')?></p></div><a class="btn btn-primary" href="sales.php">＋ Record a sale</a></div>
<div class="row g-3 mb-4"><div class="col-6 col-xl-3"><div class="card stat-card"><div class="d-flex justify-content-between align-items-center mb-3"><span class="stat-label">Today's sales</span><span class="stat-icon">₦</span></div><div class="stat-value"><?=money($today['total'])?></div><div class="small text-secondary mt-2"><?= (int)$today['count']?> transactions</div></div></div><div class="col-6 col-xl-3"><div class="card stat-card"><div class="d-flex justify-content-between align-items-center mb-3"><span class="stat-label">Today's expenses</span><span class="stat-icon">−</span></div><div class="stat-value"><?=money($expenses)?></div><div class="small text-secondary mt-2">Recorded expenses</div></div></div><div class="col-6 col-xl-3"><div class="card stat-card"><div class="d-flex justify-content-between align-items-center mb-3"><span class="stat-label">Outstanding debt</span><span class="stat-icon">↗</span></div><div class="stat-value"><?=money($debt)?></div><div class="small text-secondary mt-2">Unpaid sales balance</div></div></div><div class="col-6 col-xl-3"><div class="card stat-card"><div class="d-flex justify-content-between align-items-center mb-3"><span class="stat-label">Products / low stock</span><span class="stat-icon">□</span></div><div class="stat-value"><?=$productCount?> <span class="fs-6 text-warning">/ <?=$lowStock?></span></div><div class="small text-secondary mt-2"><a href="low_stock.php">View items needing attention</a></div></div></div></div>
<div class="row g-4"><div class="col-lg-8"><div class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold mb-0">Recent sales</h2><a href="sales.php">View all</a></div><?php if(!$recent):?><div class="empty-state"><div class="fs-1 mb-2">↗</div><h3 class="h6">Your first sale is one step away</h3><p class="mb-3">Add products, then record a sale to see activity here.</p><a class="btn btn-primary btn-sm" href="products.php">Add a product</a></div><?php else:?><div class="table-responsive"><table class="table"><thead><tr><th>Sale</th><th>Customer</th><th>Total</th><th>Paid</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $s):?><tr><td>#<?= (int)$s['id']?></td><td><?=e($s['customer']?:'Walk-in customer')?></td><td><?=money($s['total'])?></td><td><?=money($s['amount_paid'])?></td><td><?=date('d M, H:i',strtotime($s['created_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></div><div class="col-lg-4"><div class="card"><div class="card-body"><h2 class="h5 fw-bold mb-3">Quick actions</h2><div class="d-grid gap-2"><a class="btn btn-outline-primary text-start" href="products.php">＋ Add / manage products</a><a class="btn btn-outline-primary text-start" href="low_stock.php">⚠ Review low-stock alerts</a><a class="btn btn-outline-primary text-start" href="sales.php">＋ Record a sale</a><a class="btn btn-outline-primary text-start" href="customers.php">＋ Add a customer</a><a class="btn btn-outline-primary text-start" href="expenses.php">＋ Record an expense</a><a class="btn btn-outline-primary text-start" href="reports.php">↓ Download reports</a></div></div></div><div class="card mt-3"><div class="card-body"><h2 class="h6 fw-bold">Today's cash collected</h2><div class="stat-value text-success"><?=money($today['paid'])?></div><p class="small muted mb-0">Total amount entered as paid for today's sales.</p></div></div></div></div><?php require __DIR__.'/includes/footer.php';?>
